13	
14	export function ExpiryCapture({ onConfirm }: { onConfirm: (expiry: AppliedExpiry) => void }) {
15	  const [open, setOpen] = useState(false);
16	  const [busy, setBusy] = useState(false);
17	  const [error, setError] = useState<string | null>(null);
18	  const [result, setResult] = useState<ExpiryExtractionResponse | null>(null);
19	  const [date, setDate] = useState('');
20	
21	  function reset() {
22	    setResult(null);
23	    setDate('');
24	    setError(null);
25	  }
26	
27	  async function read(photos: Blob[]) {
28	    setBusy(true);
29	    setError(null);
30	    try {
31	      const r = await scanApi.readExpiry(photos[0]);
32	      setResult(r);
33	      setDate(r.needsUserChoice ? '' : (r.suggestedDate ?? ''));
34	    } catch (e) {
35	      setError(e instanceof Error ? e.message : "We couldn't read that photo.");
36	    } finally {
37	      setBusy(false);
38	    }
39	  }
40	
41	  function confirm() {
42	    if (!result) return;
43	    const wasRead = result.candidates.includes(date);
44	    onConfirm({ date, source: wasRead ? 'photo' : 'manual', rawText: wasRead ? result.rawText : null });
45	    setOpen(false);
46	    reset();
47	  }
48	
49	  const year = new Date().getFullYear();
50	  const packaged = result?.dateType === 'packaged_on';
51	
52	  return (
53	    <>
54	      <div>
55	        <Button variant="secondary" onClick={() => setOpen(true)}>
