async (page) => {
  let posts = 0;
  await page.route('**/api/vision/expiry', r => r.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify({ rawText: 'BB 12/12/2026', dateType: 'best_before', suggestedDate: '2026-12-12', candidates: ['2026-12-12'], needsUserChoice: false, yearInferred: false, regexCrossCheck: 'agree', confidence: 'high' }) }));
  await page.route('**/api/pantry', r => { if (r.request().method()==='POST') posts++; return r.continue(); });
  const qty = page.getByLabel(/Quantity you have/).first();
  await qty.fill('2').catch(()=>{});
  const b64 = await page.evaluate(() => { const c=document.createElement('canvas'); c.width=40;c.height=40; const x=c.getContext('2d'); x.fillStyle='#c00'; x.fillRect(0,0,40,40); return c.toDataURL('image/png').split(',')[1]; });
  await page.getByRole('button', { name: 'Photo of date' }).click();
  const dlg = page.getByRole('dialog');
  await dlg.locator('input[type=file]').setInputFiles({ name: 'd.png', mimeType: 'image/png', buffer: Buffer.from(b64, 'base64') });
  await dlg.getByRole('button', { name: 'Read date' }).click();
  await page.waitForTimeout(1500);
  const badge = await dlg.getByText('Read by AI, please confirm').isVisible();
  const date = dlg.locator('input[type=date]');
  await date.focus();
  await page.keyboard.press('Enter');
  await page.waitForTimeout(2000);
  return { posts, url: page.url(), badge, dialogOpen: await dlg.isVisible(), dateVal: await date.inputValue() };
}

