async (page) => {
  const reqs = [];
  page.on('request', r => { if (r.url().includes('/api/pantry') && r.method() !== 'GET') reqs.push(r.method() + ' ' + r.url()); });
  await page.getByRole('button', { name: 'Adjust' }).first().click();
  const input = page.getByLabel('Now have');
  const pre = await input.inputValue();
  await input.fill('');
  await page.getByRole('button', { name: 'Save' }).click();
