  const formOpen = await input.isVisible();
  if (formOpen) await page.getByRole('button', { name: 'Cancel' }).click();
  await page.reload(); await page.waitForTimeout(2500);
  return { pre, reqs, formOpen, after: (await page.locator('main').innerText()).match(/QA Apples\n\n[^\n]+/)?.[0] };
}

