async (page) => {
  await page.unroute('**/api/products/lookup').catch(()=>{});
  await page.getByRole('button', { name: /Log food/ }).first().click();
  const d = page.getByRole('dialog');
  await d.getByRole('tab', { name: 'Scan' }).or(d.getByRole('button', { name: 'Scan', exact: true })).first().click();
  await d.getByLabel('Type barcode').fill('3017620422003');
  await d.getByRole('button', { name: 'Look up' }).click();
  await d.getByRole('button', { name: 'Scan another' }).waitFor({ timeout: 20000 }).catch(()=>{});
  const txt = (await d.innerText()).slice(0, 400);
  const unitSel = d.getByRole('combobox', { name: 'Unit' });
  if (!(await unitSel.count())) return { txt };
  const opts = await unitSel.evaluate(s => [...s.options].map(o => o.value));
  const def = await unitSel.inputValue();
  const other = opts.find(o => o !== def);
  await unitSel.selectOption(other);
  const changed = await unitSel.inputValue();
  await d.getByRole('button', { name: 'Scan another' }).click();
  await d.getByLabel('Type barcode').fill('3017620422003');
  await d.getByRole('button', { name: 'Look up' }).click();
  await d.getByRole('button', { name: 'Scan another' }).waitFor({ timeout: 20000 });
  const after = await d.getByRole('combobox', { name: 'Unit' }).inputValue();
  return { opts, def, changed, after };
}

