async (page) => {
  await page.keyboard.press('Escape');
  await page.goto('http://localhost:3100/pantry'); await page.waitForTimeout(2500);
  await page.getByRole('button', { name: 'Adjust' }).first().click();
  await page.getByLabel('Now have').fill('0');
  await page.getByRole('button', { name: 'Save' }).click();
  await page.waitForTimeout(2000);
  const inc = page.getByLabel('Include empty');
  if (await inc.count() && !(await inc.isChecked())) await inc.click();
  await page.waitForTimeout(2000);
  const before = (await page.locator('main').innerText()).match(/QA Apples[\s\S]{0,140}/)?.[0];
  const resps = [];
  page.on('response', r => { if (r.url().includes('/api/pantry/') && r.request().method() !== 'GET') resps.push(r.request().method() + ' ' + r.status()); });
  await page.getByRole('button', { name: 'Edit' }).first().click();
  await page.waitForTimeout(800);
  const s = (await page.getByRole('dialog').count()) ? page.getByRole('dialog') : page.locator('main');
  const qty = await s.getByRole('textbox', { name: 'Quantity' }).inputValue();
  await s.getByRole('button', { name: /^Save/ }).click();
  await page.waitForTimeout(2500);
  const alerts = await page.getByRole('alert').allInnerTexts();
  const dialogOpen = await page.getByRole('dialog').count();
  const after = (await page.locator('main').innerText()).match(/QA Apples[\s\S]{0,140}/)?.[0];
  return { before, qty, resps, alerts, dialogOpen, after };
}

